using System.Windows;namespace OncaPDV.Desktop;public partial class SeparateOrderWindow:Window{public string CustomerName=>CustomerBox.Text.Trim();public string Phone=>PhoneBox.Text.Trim();public string Notes=>NotesBox.Text.Trim();public SeparateOrderWindow(decimal total,string? customer=null,string? phone=null,string? notes=null){InitializeComponent();TotalText.Text=$"Total do carrinho: {total:C}";CustomerBox.Text=customer??"";PhoneBox.Text=phone??"";NotesBox.Text=notes??"";}private void Save_Click(object sender,RoutedEventArgs e){if(CustomerName.Length<2){MessageBox.Show("Informe o nome do cliente.","Pedido",MessageBoxButton.OK,MessageBoxImage.Warning);CustomerBox.Focus();return;}DialogResult=true;}}